    explanation: 'マンション管理適正化法は、従前の管理受託契約と同一の条件で管理受託契約を更新しようとする場合には、区分所有者等全員に対する説明会の開催を要せず、当該マンションの管理者等に対して重要事項を記載した書面を交付して説明すれば足りるとする特則を設けている。契約条件に変更がある場合には、この特則は適用されない。\n\n【図解】更新時の特則\n　場面｜説明会｜書面と説明\n　同一の条件で更新する｜開催は不要｜全員に書面を交付し、管理者等に説明\n　条件を変更して更新する｜開催が必要｜新規契約と同様の手続\n　管理者等が置かれていない｜開催が必要｜区分所有者等に対して説明\n　⇒ 同一の条件とは、管理組合に不利とならない変更を含む概念とされる\n　⚠ 委託業務費の増額は同一の条件に当たらない。減額や契約期間の短縮は同一条件と扱われ得る。',
