    explanation: '重要事項説明書（第72条）は契約締結の意思決定に資するよう契約締結前に交付・説明される書面であるのに対し、契約成立時の書面（第73条）は、実際に締結された契約の内容を確認するために契約締結後遅滞なく交付される書面である。両者は記載事項の重なりはあるが、交付の時期・機能を異にする別個の制度として整理されている。\n\n【図解】重要事項説明書と法73条書面\n　項目｜重要事項説明書｜法73条書面\n　交付の時期｜契約の締結前｜契約締結後遅滞なく\n　機能｜契約するかどうかの判断材料｜締結された契約内容の確認\n　主任者の関与｜記名し、かつ説明する｜記名する（説明義務はない）\n　交付先｜区分所有者等全員｜管理者等（不在なら区分所有者等全員）\n　⇒ 記載事項は重なるが、交付の時期と機能を異にする別個の制度である\n　⚠ 法73条書面に説明義務はない。説明が必要なのは重要事項説明書である。',
