    explanation: 'マンション管理適正化法第1条は、この法律は、マンションの管理の適正化を図るための基本方針の策定、マンション管理士の資格を定め、マンション管理業者の登録制度を実施する等の措置を講ずることにより、マンションの管理の適正化を推進し、もってマンションにおける良好な居住環境の確保を図り、国民生活の安定向上と国民経済の健全な発展に寄与することを目的とすると定める。\n\n【図解】適正化法の目的と手段\n　手段｜内容｜位置付け\n　基本方針の策定｜国土交通大臣が定める｜管理の適正化を推進する指針\n　資格制度｜マンション管理士、管理業務主任者｜専門性の確保\n　業者規制｜登録制度、重要事項説明、財産の分別管理｜管理組合の保護\n　⇒ これらを通じて良好な居住環境の確保と国民の住生活の安定向上を図る\n　⚠ 法の目的は管理の適正化と良好な居住環境の確保であり、管理業者の育成そのものではない。',
