    explanation: '管理計画認定制度においては、認定を受けたマンションがその後、認定管理計画に従った管理を行っていないと認められる場合や、不正の手段により認定を受けたことが判明した場合等には、認定を行った都道府県知事等が認定を取り消すことができる。都道府県知事等は、あらかじめ認定管理者等に対して実施状況の報告を求め、又は改善に必要な措置を命ずることができ、これに従わないときに取消しに至る。取り消されると、認定に伴う融資の優遇等の効果も受けられなくなる。\n\n【図解】認定後の監督の流れ\n　段階｜内容｜主体\n　報告の徴収｜認定管理計画の実施状況の報告を求める｜都道府県知事等\n　改善命令｜改善に必要な措置を命ずる｜都道府県知事等\n　認定の取消し｜命令違反、不正な認定等の場合｜都道府県知事等\n　⇒ 認定は取得して終わりではなく、基準への適合を維持する必要がある\n　⚠ 取消しを行うのは国土交通大臣ではなく、認定をした都道府県知事等である。',
