    explanation: '専任の管理業務主任者の専任とは、宅地建物取引業法における専任の宅地建物取引士と同様、当該事務所に常勤し、専らその事務所における管理業務主任者としての職務に従事し得る状態にあることをいうと解されている。他の法人の常勤役員を兼ねることや、実態を伴わない名義上の専任は認められない。設置基準は管理組合30ごとに1名以上（端数は切上げ）であり、これを欠くに至ったときは2週間以内に必要な措置を執らなければならない。\n\n【図解】専任の要件\n　要素｜内容｜認められない例\n　常勤性｜その事務所に常時勤務している｜他社の常勤役員を兼ねる\n　専従性｜専ら管理業務主任者の職務に従事し得る｜名義だけを貸している\n　人数｜管理組合30ごとに1名以上（端数切上げ）｜欠員は2週間以内に補充\n　⇒ 実態を伴わない名義上の専任は監督処分の対象となる\n　⚠ 事務所に置かれる専任の管理業務主任者は成年者であることが必要。登録自体の要件と区別する。',
