    correctKey: 'C',
    explanation: '「登録の取消し」（マンション管理適正化法第83条等）は、マンション管理業者の法令違反等を理由として行政庁が行う不利益処分（監督処分）である。これに対し、マンション管理業者が死亡・廃業等をした場合の届出に伴う登録の失効は、当事者からの届出により登録がその効力を失うものであり、法的性質を異にする。登録取消しを受けた者は、取消しの日から5年を経過しない限り、新たな登録を受けることができない点が重要な相違点である。\n\n【図解】登録の取消しと抹消\n　手続｜性質｜場面\n　登録の取消し｜監督処分（不利益処分）｜法令違反、不正な登録、欠格事由への該当\n　廃業等による失効｜届出により登録が効力を失う｜死亡、合併消滅、破産、解散、廃止\n　登録の抹消｜登録簿から消す事務手続｜登録が効力を失ったときに行われる\n　⇒ 取消しは制裁、抹消は登録簿を整理するための事務処理である\n　⚠ 取消しを受けると5年間は再登録できないが、自主的な廃業にはこの制限はない。',
    difficulty: 'advanced',
