    correctKey: 'A',
    explanation: '法人であるマンション管理業者について、その役員のうちに登録拒否事由に該当する者があるときは、当該法人自体の登録も拒否される。これは法人の実質的な意思決定を担う役員の適格性を通じて、法人全体の適格性を判断する趣旨である。ここでいう役員には、業務を執行する社員、取締役、執行役又はこれらに準ずる者が含まれ、相談役や顧問等であっても、法人に対し取締役と同等以上の支配力を有すると認められる者は役員として扱われる。\n\n【図解】法人に特有の登録拒否事由\n　事由｜内容｜結果\n　役員の欠格｜役員のうちに拒否事由に該当する者がある｜法人として登録を受けられない\n　主任者の不足｜専任の管理業務主任者が基準に満たない｜登録を受けられない\n　財産的基礎｜基準資産額が300万円に満たない｜登録を受けられない\n　⇒ 法人自体に問題がなくても、役員個人の欠格により登録が拒否される\n　⚠ 役員には登記された取締役だけでなく、実質的な支配力を有する者も含まれる。',
