    correctKey: 'D',
    explanation: 'マンション管理適正化法は、マンション管理士制度（専門家の育成・活用）、マンション管理業者の登録制度（管理業者の適正な業務運営の確保）、マンション管理適正化推進計画・管理計画認定制度（地方公共団体の関与による管理の適正化の推進）等、複数の制度から構成される法律である。これらは相互に関連しながら、区分所有法を前提としたマンションの管理の適正化を、行政・専門家・管理業者それぞれの側面から支える仕組みとなっている。\n\n【図解】適正化法の3つの柱\n　柱｜内容｜キーとなる数値\n　マンション管理士制度｜資格、登録、義務、名称独占｜欠格2年、5年ごとの講習\n　管理業者の登録制度｜登録、重要事項説明、分別管理、報告｜登録5年、30組合に1名\n　行政の関与｜基本方針、推進計画、管理計画認定｜認定の有効期間5年\n　⇒ 3つの柱が相互に関連しながら管理の適正化を推進する構造になっている\n　⚠ 期間の数値（2年・5年・30日・2週間）は柱ごとに整理しないと混同する。',
    difficulty: 'basic',
